"""Fifty individually authored scenarios, two meaningfully different versions each.

Shared context belongs to one pair only. No random paraphrasing or corpus imports.
Labels are author judgements; independent human double annotation is still needed.
"""

PAIRS = []


def pair(topic, context, a, b, closing, labels_a, labels_b, change):
    PAIRS.append(dict(topic=topic, context=context, a=a, b=b, closing=closing,
                      labels_a=labels_a, labels_b=labels_b, change=change))


